glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 v_color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  v_color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 v_color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
uniform sampler2D noiseTexture;
layout(std140) uniform HeatWaveParams {
  vec4 heatTint;
  vec2 scale;
  float strength;
  float speed;
  float edgeFadeTop;
  float edgeFadeBottom;
  float edgeFadeLeft;
  float edgeFadeRight;
};
vec4 frag () {
  float time = cc_time.x;
  float edgeMask = 1.0;
  if (edgeFadeTop > 0.0) {
    float topFade = smoothstep(1.0 - edgeFadeTop, 1.0, uv0.y);
    edgeMask *= (1.0 - topFade);
  }
  if (edgeFadeBottom > 0.0) {
    float bottomFade = smoothstep(0.0, edgeFadeBottom, uv0.y);
    edgeMask *= bottomFade;
  }
  if (edgeFadeLeft > 0.0) {
    float leftFade = smoothstep(0.0, edgeFadeLeft, uv0.x);
    edgeMask *= leftFade;
  }
  if (edgeFadeRight > 0.0) {
    float rightFade = smoothstep(1.0 - edgeFadeRight, 1.0, uv0.x);
    edgeMask *= (1.0 - rightFade);
  }
  vec2 noiseUV1 = uv0 * scale;
  noiseUV1.y -= time * speed * 0.15;
  noiseUV1.x += sin(time * speed * 0.8) * 0.1;
  float noise1 = texture(noiseTexture, noiseUV1).r;
  vec2 noiseUV2 = uv0 * scale * 1.7;
  noiseUV2.y -= time * speed * 0.23;
  noiseUV2.x -= cos(time * speed * 1.2) * 0.08;
  float noise2 = texture(noiseTexture, noiseUV2).r;
  vec2 noiseUV3 = uv0 * scale * 0.6;
  noiseUV3.y -= time * speed * 0.1;
  float noise3 = texture(noiseTexture, noiseUV3).r;
  float combinedNoise = noise1 * 0.5 + noise2 * 0.3 + noise3 * 0.2;
  float wave1 = sin(uv0.y * 12.0 + time * speed * 2.5);
  float wave2 = sin(uv0.x * 8.0 + time * speed * 1.8);
  float wave3 = cos(uv0.y * 20.0 + time * speed * 3.2);
  float wavePattern = (wave1 + wave2 * 0.5 + wave3 * 0.3) / 1.8;
  vec2 distortion = vec2(0.0);
  distortion.x = (combinedNoise - 0.5) * strength * 0.8 * edgeMask;
  distortion.x += wave2 * strength * 0.2 * edgeMask;
  distortion.y = wavePattern * strength * 0.4 * edgeMask;
  distortion.y += (noise2 - 0.5) * strength * 0.3 * edgeMask;
  vec2 distortedUV = uv0 + distortion;
  vec4 color = texture(cc_spriteTexture, distortedUV);
  color.rgb = mix(color.rgb, heatTint.rgb, heatTint.a * color.a);
  float shimmer = sin(time * speed * 4.0 + combinedNoise * 10.0) * 0.5 + 0.5;
  color.rgb += vec3(shimmer * 0.02);
  color *= v_color;
  return color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

